param([Parameter(Mandatory=$true)][string]$PackageRoot,[switch]$LiveQuota,[switch]$LiveActivity,[switch]$LiveTokens,[switch]$LiveSurface,[string]$DragonDirectory,[switch]$DragonAssetsOnly,[switch]$RenderDocs,[switch]$RenderDials,[switch]$MotionProof,[switch]$Preview3Proof,[switch]$SwitchProof,[switch]$BehaviorProof,[switch]$VideoProof,[string]$PetState)
$ErrorActionPreference='Stop'
$repo=Split-Path -Parent $PSScriptRoot;$out=Join-Path $PSScriptRoot ('output\companion-'+[guid]::NewGuid().ToString('N'));$null=New-Item -ItemType Directory -Path $out
$files=@('Manager.cs','IconAssets.cs','WallpaperLibrary.cs','GalleryControls.cs','GalleryManager.cs','MediaPreviewJob.cs','SoftwareUpdate.cs','ManagerUpdates.cs','ManagerPetAppearance.cs','ManagerFollow.cs','CodexFollow.cs','PetCardPalette.cs','DailyUpdates.cs','CloudPets.cs','BuiltinDownloads.cs','CompanionCore.cs','WindowResize.cs','CompanionBehavior.cs','CompanionVideo.cs','CompanionOverlay.cs','CompanionSettings.cs','CompanionQuota.cs','CompanionWindow.cs','CompanionPage.cs','DouyinSpark.cs','DouyinAccessibility.cs','DouyinWorker.cs','DouyinLauncher.cs','DouyinNativeUia.cs','CompanionAutomation.cs','ManagerDouyin.cs','CompanionActivity.cs','CompanionBailong.cs','CompanionTokens.cs','HubPopupMenu.cs')|ForEach-Object{Join-Path $repo ('source\'+$_)}
$exe=Join-Path $PackageRoot CompanionTests.exe;$report=Join-Path $out result.json
if(Test-Path -LiteralPath $exe){throw 'Companion test executable already exists'}
& (Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319\csc.exe') /nologo /debug+ /target:winexe /main:CompanionTests /platform:x64 /codepage:65001 ("/out:$exe") ("/resource:"+(Join-Path $repo 'source\assets\sounds\click.wav')+",CodexHub.ClickSound") /r:System.Windows.Forms.dll /r:System.Drawing.dll /r:System.Web.Extensions.dll /r:Accessibility.dll /r:UIAutomationClient.dll /r:UIAutomationTypes.dll /r:WindowsBase.dll /r:"$repo\source\assets\windows\Interop.UIAutomationClient.dll" /resource:"$repo\source\assets\windows\Interop.UIAutomationClient.dll,CodexHub.UIAutomationInterop" "/lib:$env:WINDIR\Microsoft.NET\Framework64\v4.0.30319\WPF" /r:System.IO.Compression.dll /r:System.IO.Compression.FileSystem.dll $files (Join-Path $PSScriptRoot CompanionTests.cs) (Join-Path $PSScriptRoot PetBehaviorTests.cs) (Join-Path $PSScriptRoot PetPreview3Tests.cs)
if($LASTEXITCODE -ne 0){throw 'Companion test compilation failed'}
$arguments='"'+$report+'" "'+[IO.Path]::GetFullPath($PackageRoot)+'"';if($MotionProof){$arguments+=' --motion-proof'};if($RenderDials){$arguments+=' --render-dials'};if($RenderDocs){$arguments+=' --render-docs'};if($LiveQuota){$arguments+=' --live-quota'};if($LiveActivity){$arguments+=' --live-activity'};if($LiveTokens){$arguments+=' --live-tokens'};if($LiveSurface){$arguments+=' --live-surface'};if($DragonDirectory){$arguments+=' --dragon '+('"'+$DragonDirectory+'"');if($DragonAssetsOnly){$arguments+=' --assets-only'}}
if($SwitchProof){$arguments+=' --switch-proof'};if($Preview3Proof){$arguments+=' --preview3-proof'};if($BehaviorProof){$arguments+=' --behavior-proof'};if($VideoProof){$arguments+=' --video-proof'};if($PetState){$arguments+=' '+('"'+[IO.Path]::GetFullPath($PetState)+'"')}
try{$process=Start-Process $exe -ArgumentList $arguments -WindowStyle Hidden -PassThru;if(-not $process.WaitForExit(120000)){throw 'Companion tests timed out'};$data=[IO.File]::ReadAllText($report)|ConvertFrom-Json;if($process.ExitCode -ne 0 -or -not $data.pass){throw $data.error};$data|ConvertTo-Json -Depth 5 -Compress;Write-Output ('Report: '+$report)}finally{Remove-Item -LiteralPath $exe -Force -ErrorAction SilentlyContinue;Remove-Item -LiteralPath ([IO.Path]::ChangeExtension($exe,".pdb")) -Force -ErrorAction SilentlyContinue}
